"""Actual three-role objective assessment, commentary, report, consultation file and notices."""
import asyncio,json,pathlib,hashlib,datetime,sys
from browser_support import Browser
from gap_fill_walkthrough import api
from learning_plan_walkthrough import register,PASSWORD
from learning_materials_walkthrough import file_input
sys.stdout.reconfigure(encoding='utf-8')
ROOT=pathlib.Path(__file__).resolve().parents[1]
async def main():
 s,t,p=register('STUDENT'),register('TEACHER'),register('PARENT')
 at=(datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=8)))+datetime.timedelta(days=25)).replace(hour=15,minute=0,second=0,microsecond=0)
 slot,_=api('POST','/scheduling/availability-slots',{'startAt':at.isoformat(),'endAt':(at+datetime.timedelta(hours=1)).isoformat()},t['token']);booking,_=api('POST','/booking/bookings',{'teacherId':t['id'],'slotId':slot['slotId'],'subject':'数学','bookingType':'FORMAL'},s['token']);api('POST','/booking/booking-requests/'+booking['bookingId']+':decide?decision=approve',{},t['token'])
 profile,_=api('GET','/student/me/profile',token=s['token']);api('POST','/parent/me/children',{'studentNo':profile['studentNo'],'relation':'母亲'},p['token']);api('POST','/parent/me/children:confirm',{},s['token']);children,_=api('GET','/parent/me/children',token=p['token'])
 async with Browser(ROOT/'.walk'/'assessments-messages',port=9238) as b:
  await b.role('TEACHER',t['phone'],PASSWORD,'/teacher/dashboard');await b.click('阶段小测与报告','a');await b.until('document.querySelector("select[name=lesson] option")!==null','eligible lesson')
  for selector,value in [('#assessment-title','一次函数阶段小测'),('#assessment-scope','检验一次函数基础运算，仅覆盖本题范围'),('#assessment-question-0','2×3 等于多少？')]+[('#assessment-choice-0-'+str(i),str(n)) for i,n in enumerate([6,5,7,8])]:await b.fill(selector,value)
  await b.click('保存草稿');await b.until('document.querySelector("article")?.innerText.includes("教师草稿")','draft persisted');await b.shot('teacher-assessment-draft-desktop');await b.click('发布小测');await b.until('document.querySelector("article")?.innerText.includes("已发布")','published')
  quizzes,_=api('GET','/learning/assessments',token=s['token']);q=quizzes['content'][0];assert q['questions'][0]['correctIndex'] is None,'answer redacted before attempt'
  await b.role('STUDENT',s['phone'],PASSWORD,'/learning/assessments');await b.until('document.querySelector("input[type=radio]")!==null','student actual quiz');await b.js('document.querySelector("input[type=radio]").click()');await b.click('提交作答并评分');await b.until('document.body.innerText.includes("本次答对 1/1 题")','real graded result');await b.viewport(375);await b.shot('student-assessment-score-mobile375');await b.viewport(1280)
  await b.role('TEACHER',t['phone'],PASSWORD,'/learning/assessments');await b.until('document.querySelector("textarea[id^=assessment-comment]")!==null','teacher attempt');await b.fill('textarea[id^=assessment-comment]','本题计算正确，下次练习移项');await b.click('保存批注');await b.until('document.querySelector("article").innerText.includes("下次练习移项")','comment saved');await b.shot('teacher-assessment-comment-desktop')
  await b.role('PARENT',p['phone'],PASSWORD,'/learning/assessments?childProfileId='+children[0]['studentId']);await b.until('document.body.innerText.includes("下次练习移项")','guardian real comment');assert await b.js('document.querySelector("textarea")===null && document.querySelector("input[type=radio]")===null'),'guardian readonly';await b.viewport(375);await b.shot('parent-assessment-report-mobile375');await b.viewport(1280)
  conversation,_=api('POST','/messaging/conversations',{'teacherId':t['id'],'subject':'数学小测资料'},s['token']);cid=conversation['conversationId'];await b.role('STUDENT',s['phone'],PASSWORD,'/messages?conversation='+cid);await b.until('document.querySelector("input[type=file]")!==null','consultation ready');await file_input(b,'document.querySelector("input[type=file]")','课前资料.pdf');await b.until('document.body.innerText.includes("附件：课前资料.pdf") && document.body.innerText.includes("下载附件")','file message persisted');await b.shot('student-consultation-file-desktop')
  messages,_=api('GET','/messaging/conversations/'+cid+'/messages',token=s['token']);file=next(m['attachmentId'] for m in messages if m['attachmentId']);await b.role('TEACHER',t['phone'],PASSWORD,'/messages?conversation='+cid);await b.until('document.body.innerText.includes("下载附件")','teacher file reception');r=await b.js('(async()=>{const r=await fetch("/api/v1/messaging/files/'+file+'/download");return {status:r.status,bytes:[...new Uint8Array(await r.arrayBuffer())],cache:r.headers.get("Cache-Control")};})()');assert r['status']==200 and 'no-store' in r['cache'] and bytes(r['bytes']).startswith(b'%PDF-'),'actual private attachment bytes'
  await b.role('STUDENT',s['phone'],PASSWORD,'/student/dashboard');await b.click('展开全部');await b.until('document.querySelector("nur-notice-center .notice-toggle")!==null','student dashboard notices ready');await b.js('document.querySelector("nur-notice-center .notice-toggle").click()');await b.until('document.querySelector("nur-notice-center #notice-list")?.innerText.includes("阶段小测") || document.querySelector("nur-notice-center #notice-list")?.innerText.includes("小测")','assessment notifications');await b.js('document.querySelector("nur-notice-center").scrollIntoView()');await b.viewport(375);await b.shot('student-notice-mobile375');assert await b.js('(()=>{const x=[...document.querySelectorAll("nur-notice-center button")].find(x=>x.textContent.trim()==="标记已读");if(!x)return false;x.click();return true;})()'),'mark notice read'
 print('PASS: teacher draft/publish, real student grade, teacher comment, guardian readonly report, private consultation file and notice read; 6 screenshots')
if __name__=='__main__':asyncio.run(main())
